carrier-drift-mobility-einstein-relation.js:
(() => {
  'use strict';
  const munEl = document.getElementById('cd-mun'), mupEl = document.getElementById('cd-mup');
  const nEl = document.getElementById('cd-n'), tEl = document.getElementById('cd-t');
  const dfResEl = document.getElementById('cd-res-diff'), cdResEl = document.getElementById('cd-res-cond');

  const q = 1.602176634e-19; // C
  const k_B = 1.380649e-23; // J/K

  function update() {
    const mu_n = parseFloat(munEl.value), mu_p = parseFloat(mupEl.value);
    const n = parseFloat(nEl.value), T_K = parseFloat(tEl.value);

    if (isNaN(mu_n) || isNaN(mu_p) || isNaN(n) || isNaN(T_K) || mu_n <= 0 || mu_p <= 0 || n <= 0 || T_K <= 0) return;

    // Thermal voltage: V_t = k_B * T / q
    const V_t = (k_B * T_K) / q;

    // Einstein relation: D = mu * V_t  [cm^2 / s]
    const D_n = mu_n * V_t;
    const D_p = mu_p * V_t;

    // Electrical conductivity for n-type (n >> p): sigma = q * n * mu_n  [1 / (ohm * cm)]
    const sigma = q * n * mu_n;
    const rho = 1.0 / sigma; // ohm * cm

    dfResEl.textContent = 'Diffusivity: D_n = ' + D_n.toFixed(2) + ' cm²/s | D_p = ' + D_p.toFixed(2) + ' cm²/s';
    cdResEl.textContent = 'Conductivity σ = ' + sigma.toFixed(3) + ' (Ω·cm)⁻¹ | Resistivity ρ = ' + rho.toFixed(3) + ' Ω·cm (V_t = ' + (V_t*1000).toFixed(2) + ' mV @ ' + T_K + ' K)';
  }

  [munEl, mupEl, nEl, tEl].forEach(el => el.addEventListener('input', update));
  update();
})();

case-kebab-camel-snake-converter.js:
(() => {
  'use strict';
  const inEl = document.getElementById('case-input');
  const camelEl = document.getElementById('res-camel'), pascalEl = document.getElementById('res-pascal');
  const snakeEl = document.getElementById('res-snake'), kebabEl = document.getElementById('res-kebab'), constEl = document.getElementById('res-constant');

  function splitWords(str) {
    return str
      .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
      .replace(/[^a-zA-Z0-9]+/g, ' ')
      .trim()
      .toLowerCase()
      .split(/\s+/)
      .filter(Boolean);
  }

  function update() {
    const raw = inEl.value.trim();
    if (!raw) return;

    const words = splitWords(raw);
    if (words.length === 0) return;

    const camel = words[0] + words.slice(1).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('');
    const pascal = words.map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('');
    const snake = words.join('_');
    const kebab = words.join('-');
    const constCase = words.join('_').toUpperCase();

    camelEl.textContent = camel;
    pascalEl.textContent = pascal;
    snakeEl.textContent = snake;
    kebabEl.textContent = kebab;
    constEl.textContent = constCase;
  }

  inEl.addEventListener('input', update);
  update();
})();

cbse-class-10-cgpa-to-percentage-convert.js:
(() => {
  'use strict';
  const cgpaEl = document.getElementById('cbse-cgpa'), subEl = document.getElementById('cbse-sub');
  const pctResEl = document.getElementById('cbse-res-pct'), subResEl = document.getElementById('cbse-res-sub');

  function update() {
    const cgpa = parseFloat(cgpaEl.value), gp = parseFloat(subEl.value);
    if (isNaN(cgpa) || cgpa <= 0 || cgpa > 10.0) return;

    // Official CBSE formula: Overall Percentage = CGPA * 9.5
    const overall_pct = cgpa * 9.5;

    // Subject percentage = GP * 9.5
    let subStr = '';
    if (!isNaN(gp) && gp >= 1 && gp <= 10) {
      const sub_pct = gp * 9.5;
      let grade = '';
      if (gp === 10) grade = 'A1 (91-100)';
      else if (gp === 9) grade = 'A2 (81-90)';
      else if (gp === 8) grade = 'B1 (71-80)';
      else if (gp === 7) grade = 'B2 (61-70)';
      else if (gp === 6) grade = 'C1 (51-60)';
      else if (gp === 5) grade = 'C2 (41-50)';
      else if (gp === 4) grade = 'D (33-40)';
      else grade = 'E (Failed)';
      subStr = 'Subject Percentage: ' + sub_pct.toFixed(1) + '% (GP ' + gp + ' × 9.5 | Grade ' + grade + ')';
    }

    pctResEl.textContent = overall_pct.toFixed(2) + '% Equivalent Marks';
    subResEl.textContent = subStr || 'Formula: Percentage = CGPA × 9.5 (Approved by CBSE Examination Bylaws)';
  }

  cgpaEl.addEventListener('input', update);
  subEl.addEventListener('input', update);
  update();
})();

