(() => {
  'use strict';
  const fEl = document.getElementById('ht-f'), hbEl = document.getElementById('ht-hb');
  const hmEl = document.getElementById('ht-hm'), dEl = document.getElementById('ht-d'), envEl = document.getElementById('ht-env');
  const plResEl = document.getElementById('ht-res-pl'), subResEl = document.getElementById('ht-res-sub');

  function update() {
    const f = parseFloat(fEl.value), hb = parseFloat(hbEl.value);
    const hm = parseFloat(hmEl.value), d = parseFloat(dEl.value);
    const env = envEl.value;

    if (isNaN(f) || isNaN(hb) || isNaN(hm) || isNaN(d) || f < 150 || f > 2000 || hb < 10 || hm <= 0 || d <= 0) return;

    const a_hm = ((1.1 * Math.log10(f) - 0.7) * hm) - ((1.56 * Math.log10(f)) - 0.8);
    const pl_urban = 69.55 + (26.16 * Math.log10(f)) - (13.82 * Math.log10(hb)) - a_hm + ((44.9 - (6.55 * Math.log10(hb))) * Math.log10(d));
    const pl_suburban = pl_urban - (2 * Math.pow(Math.log10(f / 28), 2)) - 5.4;
    const pl_rural = pl_urban - (4.78 * Math.pow(Math.log10(f), 2)) + (18.33 * Math.log10(f)) - 40.94;

    let selectedPL = pl_urban;
    if (env === 'suburban') selectedPL = pl_suburban;
    else if (env === 'rural') selectedPL = pl_rural;

    plResEl.textContent = 'PL = ' + selectedPL.toFixed(1) + ' dB Path Loss';
    subResEl.textContent = 'Urban: ' + pl_urban.toFixed(1) + ' dB | Suburban: ' + pl_suburban.toFixed(1) + ' dB | Rural: ' + pl_rural.toFixed(1) + ' dB';
  }

  [fEl, hbEl, hmEl, dEl].forEach(el => el.addEventListener('input', update));
  envEl.addEventListener('change', update);
  update();
})();

centrifugal-pump-affinity-laws-flow-head.js:
(() => {
  'use strict';
  const n1El = document.getElementById('pa-n1'), q1El = document.getElementById('pa-q1');
  const h1El = document.getElementById('pa-h1'), p1El = document.getElementById('pa-p1'), n2El = document.getElementById('pa-n2');
  const npResEl = document.getElementById('pa-res-newp'), qhResEl = document.getElementById('pa-res-qh');

  function update() {
    const N1 = parseFloat(n1El.value), Q1 = parseFloat(q1El.value);
    const H1 = parseFloat(h1El.value), P1 = parseFloat(p1El.value), N2 = parseFloat(n2El.value);

    if (isNaN(N1) || isNaN(Q1) || isNaN(H1) || isNaN(P1) || isNaN(N2) || N1 <= 0 || Q1 <= 0 || H1 <= 0 || P1 <= 0 || N2 <= 0) return;

    const ratio = N2 / N1;

    // Affinity Laws:
    // Flow Q2 = Q1 * ratio
    const Q2 = Q1 * ratio;
    // Head H2 = H1 * ratio^2
    const H2 = H1 * Math.pow(ratio, 2);
    // Power P2 = P1 * ratio^3
    const P2 = P1 * Math.pow(ratio, 3);

    const powerSavedPct = ((P1 - P2) / P1) * 100.0;

    npResEl.textContent = 'New Power P₂ = ' + P2.toFixed(2) + ' kW (' + powerSavedPct.toFixed(1) + '% Energy Savings)';
    qhResEl.textContent = 'New Flow Q₂ = ' + Q2.toFixed(1) + ' m³/h | New Head H₂ = ' + H2.toFixed(1) + ' m (Speed Ratio = ' + (ratio * 100).toFixed(0) + '%)';
  }

  [n1El, q1El, h1El, p1El, n2El].forEach(el => el.addEventListener('input', update));
  update();
})();

centripetal-acceleration-centripetal-for.js:
(() => {
  'use strict';
  const mEl = document.getElementById('ca-m'), vEl = document.getElementById('ca-v'), rEl = document.getElementById('ca-r');
  const acResEl = document.getElementById('ca-res-acc'), fcResEl = document.getElementById('ca-res-force');

  const g = 9.80665; // m/s^2

  function update() {
    const m = parseFloat(mEl.value), v = parseFloat(vEl.value), r = parseFloat(rEl.value);
    if (isNaN(m) || isNaN(v) || isNaN(r) || m <= 0 || v <= 0 || r <= 0) return;

    // Centripetal acceleration a_c = v^2 / r  [m / s^2]
    const a_c = Math.pow(v, 2) / r;
    const g_force = a_c / g;

    // Centripetal force F_c = m * a_c  [Newtons]
    const F_c = m * a_c;

    // Ideal frictionless roadway bank angle: tan(theta) = v^2 / (g * r)
    const tan_theta = Math.pow(v, 2) / (g * r);
    const bank_deg = (Math.atan(tan_theta) * 180.0) / Math.PI;

    acResEl.textContent = 'a_c = ' + a_c.toFixed(2) + ' m / s² (' + g_force.toFixed(2) + ' g-force)';
    fcResEl.textContent = 'Force F_c = ' + Math.round(F_c).toLocaleString() + ' N (' + (F_c/1000).toFixed(2) + ' kN) | Bank Angle θ = ' + bank_deg.toFixed(1) + '° (Speed: ' + (v * 3.6).toFixed(0) + ' km/h @ r = ' + r + ' m)';
  }

  [mEl, vEl, rEl].forEach(el => el.addEventListener('input', update));
  update();
})();

