cereal-grain-drying-equilibrium-moisture.js:
(() => {
  'use strict';
  const cEl = document.getElementById('em-crop'), tEl = document.getElementById('em-temp'), rhEl = document.getElementById('em-rh');
  const emcResEl = document.getElementById('em-res-emc'), sfResEl = document.getElementById('em-res-safe');

  function update() {
    const parts = cEl.value.split('_');
    const A = parseFloat(parts[0]);
    const B = parseFloat(parts[1]);
    const C = parseFloat(parts[2]);
    const safeMax = parseFloat(parts[3]);

    const temp_C = parseFloat(tEl.value), RH_pct = parseFloat(rhEl.value);
    if (isNaN(temp_C) || isNaN(RH_pct) || RH_pct <= 0 || RH_pct >= 100) return;

    const rh_dec = RH_pct / 100.0;

    // ASABE standard Chung-Pfost EMC equation (Dry Basis):
    // EMC_db = ( -1 / B ) * ln( -(temp_C + C) * ln(rh_dec) / A )
    // Ensure valid logarithm argument:
    const inner = -((temp_C + C) * Math.log(rh_dec)) / A;
    if (inner <= 0) return;

    const EMC_db_dec = (-1.0 / B) * Math.log(inner);
    const EMC_db = EMC_db_dec * 100.0;

    // Convert Dry Basis to Wet Basis: EMC_wb = ( EMC_db / (100 + EMC_db) ) * 100
    const EMC_wb = (EMC_db / (100.0 + EMC_db)) * 100.0;

    let status = '', color = '#22543d';

    if (EMC_wb <= safeMax) {
      status = 'SAFE LONG-TERM STORAGE (EMC ' + EMC_wb.toFixed(1) + '% ≤ Safe Limit ' + safeMax + '%: No mold risk)';
      color = '#22543d';
    } else {
      status = 'SPOILAGE RISK DANGER (EMC ' + EMC_wb.toFixed(1) + '% > Safe Limit ' + safeMax + '%: Active aeration / heated drying required!)';
      color = '#c53030';
    }

    emcResEl.textContent = 'EMC = ' + EMC_wb.toFixed(2) + '% Wet Basis (' + EMC_db.toFixed(2) + '% Dry Basis)';
    emcResEl.style.color = color;
    sfResEl.textContent = status + ' @ ' + temp_C + '°C, ' + RH_pct + '% RH';
    sfResEl.style.color = color;
  }

  cEl.addEventListener('change', update);
  tEl.addEventListener('input', update);
  rhEl.addEventListener('input', update);
  update();
})();

cfd-y-plus-boundary-layer-wall-distance-.js:
(() => {
  'use strict';
  const uEl = document.getElementById('yp-u'), lEl = document.getElementById('yp-l');
  const ypEl = document.getElementById('yp-targ'), flEl = document.getElementById('yp-fluid');
  const dyResEl = document.getElementById('yp-res-dy'), reResEl = document.getElementById('yp-res-re');

  const FLUIDS = {
    'air':   { rho: 1.225, nu: 1.51e-5 },
    'water': { rho: 1000.0, nu: 1.00e-6 }
  };

  function update() {
    const f = FLUIDS[flEl.value];
    const U = parseFloat(uEl.value), L = parseFloat(lEl.value), yPlus = parseFloat(ypEl.value);

    if (isNaN(U) || isNaN(L) || isNaN(yPlus) || U <= 0 || L <= 0 || yPlus <= 0) return;

    // Reynolds number Re = (U * L) / nu
    const Re = (U * L) / f.nu;

    // Flat plate turbulent skin friction coefficient: C_f approx = (2 * log10(Re) - 0.65)^(-2.3)
    // Or standard Schlichting formula: C_f = 0.0592 * Re^(-0.2)
    const Cf = 0.0592 * Math.pow(Re, -0.2);

    // Wall shear stress tau_w = 0.5 * rho * U^2 * Cf  [Pa]
    const tau_w = 0.5 * f.rho * Math.pow(U, 2) * Cf;

    // Friction velocity u_tau = sqrt( tau_w / rho ) = U * sqrt( Cf / 2 )  [m / s]
    const u_tau = U * Math.sqrt(Cf / 2);

    // First cell height delta_y = ( yPlus * nu ) / u_tau  [meters]
    const dy_m = (yPlus * f.nu) / u_tau;
    const dy_um = dy_m * 1e6;
    const dy_mm = dy_m * 1000;

    let dyStr = '';
    if (dy_um < 1000) dyStr = dy_um.toFixed(1) + ' μm (' + dy_mm.toFixed(4) + ' mm)';
    else dyStr = dy_mm.toFixed(3) + ' mm (' + Math.round(dy_um) + ' μm)';

    dyResEl.textContent = 'Δy = ' + dyStr + ' (Target y+ = ' + yPlus + ')';
    reResEl.textContent = 'Re = ' + Re.toExponential(2) + ' | u_τ = ' + u_tau.toFixed(2) + ' m/s (C_f = ' + Cf.toFixed(4) + ', τ_w = ' + tau_w.toFixed(1) + ' Pa)';
  }

  [uEl, lEl, ypEl].forEach(el => el.addEventListener('input', update));
  flEl.addEventListener('change', update);
  update();
})();

