    const X_pct = X * 100.0;

    xResEl.textContent = 'CSTR Conversion X = ' + X_pct.toFixed(1) + '%';
    dtResEl.textContent = 'Space Time τ = ' + tau.toFixed(1) + ' s | Damköhler Da = ' + Da.toFixed(2) + ' (V = ' + V + ' m³, v₀ = ' + v0 + ' m³/s)';
  }

  [vEl, v0El, kEl].forEach(el => el.addEventListener('input', update));
  update();
})();

