  const qEl = document.getElementById('cv-q'), dpEl = document.getElementById('cv-dp'), sgEl = document.getElementById('cv-sg');
  const cvResEl = document.getElementById('cv-res-val'), pResEl = document.getElementById('cv-res-pipe');

  function update() {
