    const T_wb = parseFloat(twbEl.value), L_over_G = parseFloat(lgEl.value);

    if (isNaN(T_in) || isNaN(T_out) || isNaN(T_wb) || isNaN(L_over_G) || T_in <= T_out || T_out <= T_wb || L_over_G <= 0) return;

