    angResEl.textContent = 'Angle θ = ' + theta_deg.toFixed(2) + '° | Cosine Distance = ' + cos_dist.toFixed(4) + ' | Euclidean Distance = ' + euc_dist.toFixed(3) + ' (' + uStr.length + '-D vectors)';
  }

