    clResEl.textContent = 'Coulomb ln Λ = ' + ln_Lambda.toFixed(1) + ' | Conductivity σ = ' + sigma.toExponential(2) + ' (Ω·m)⁻¹ (T_e=' + T_e_eV + ' eV, Z_eff=' + Z_eff + ')';
