    } else if (crcl >= 15) {
      stResEl.textContent = 'Severe Renal Impairment (15 to 29 mL/min)';
      stResEl.style.color = '#c53030';
    } else {
      stResEl.textContent = 'End-Stage Renal Disease / Kidney Failure (< 15 mL/min: Dialysis)';
      stResEl.style.color = '#c53030';
    }
  }

