crosslink-density-flory-rehner-swelling-.js:
(() => {
  'use strict';
  const vrEl = document.getElementById('flr-vr'), chiEl = document.getElementById('flr-chi');
  const nuResEl = document.getElementById('flr-res-nu'), mcResEl = document.getElementById('flr-res-mc');

  // Molar volume of toluene Vs = 106.3 cm^3 / mol; density of rubber rho = 1.0 g/cm^3
  const Vs = 106.3;
  const rho_p = 1.0;

  function update() {
    const vr = parseFloat(vrEl.value), chi = parseFloat(chiEl.value);
    if (isNaN(vr) || isNaN(chi) || vr <= 0 || vr >= 1) return;

    // Flory-Rehner equation:
    // nu_e = - [ ln(1 - vr) + vr + chi * vr^2 ] / [ Vs * ( vr^(1/3) - vr / 2 ) ]
    const numerator = -(Math.log(1 - vr) + vr + (chi * Math.pow(vr, 2)));
    const denominator = Vs * (Math.pow(vr, 1 / 3) - (vr / 2));
    const nu_e = numerator / denominator;
    const Mc = nu_e > 0 ? (rho_p / nu_e) : 0;

    nuResEl.textContent = (nu_e * 1e4).toFixed(2) + ' × 10⁻⁴ mol / cm³';
    mcResEl.textContent = 'M_c ≈ ' + Math.round(Mc).toLocaleString() + ' g / mol (Swelling Ratio Q = ' + (1 / vr).toFixed(1) + 'x)';
  }

  vrEl.addEventListener('input', update);
  chiEl.addEventListener('input', update);
  update();
})();

crosswind-headwind-runway-component-calc.js:
(() => {
  'use strict';
  const rwyEl = document.getElementById('wnd-rwy'), dirEl = document.getElementById('wnd-dir'), spdEl = document.getElementById('wnd-spd');
  const xResEl = document.getElementById('wnd-res-xwind'), hResEl = document.getElementById('wnd-res-hwind');

  function update() {
    const rwyNum = parseFloat(rwyEl.value);
    const windDir = parseFloat(dirEl.value);
    const windSpd = parseFloat(spdEl.value);

    if (isNaN(rwyNum) || isNaN(windDir) || isNaN(windSpd) || windSpd < 0) return;

    const rwyDeg = rwyNum * 10;
    // Angle between wind and runway
    let angleDiff = windDir - rwyDeg;
    while (angleDiff > 180) angleDiff -= 360;
    while (angleDiff < -180) angleDiff += 360;

    const rad = (angleDiff * Math.PI) / 180;
    // Crosswind = Wind * sin(angle)
    const crosswind = windSpd * Math.sin(rad);
    // Headwind = Wind * cos(angle)
    const headwind = windSpd * Math.cos(rad);

    const absCross = Math.abs(crosswind);
    const crossSide = crosswind > 0 ? 'Right' : 'Left';

    xResEl.textContent = absCross.toFixed(1) + ' Knots (' + (absCross > 0 ? crossSide : 'Direct') + ')';
    if (headwind >= 0) {
      hResEl.textContent = headwind.toFixed(1) + ' Knots (Headwind)';
      hResEl.style.color = '#22543d';
    } else {
      hResEl.textContent = Math.abs(headwind).toFixed(1) + ' Knots (TAILWIND WARNING)';
      hResEl.style.color = '#c53030';
    }
  }

  [rwyEl, dirEl, spdEl].forEach(el => el.addEventListener('input', update));
  update();
})();

cryogenic-nitrogen-boil-off-rate-dewar-h.js:
(() => {
  'use strict';
  const cEl = document.getElementById('bor-cryo'), qEl = document.getElementById('bor-q');
  const rResEl = document.getElementById('bor-res-rate'), mResEl = document.getElementById('bor-res-mass');

  const CRYOS = {
    'ln2': { dh_vap: 199.0, rho: 808.0, name: 'Liquid Nitrogen LN₂' },
    'lhe': { dh_vap: 20.9,  rho: 125.0, name: 'Liquid Helium LHe' },
    'lh2': { dh_vap: 446.0, rho: 71.0,  name: 'Liquid Hydrogen LH₂' },
    'lox': { dh_vap: 213.0, rho: 1141.0,name: 'Liquid Oxygen LOX' },
    'lng': { dh_vap: 510.0, rho: 422.0, name: 'Liquid Methane LNG' }
  };

  function update() {
    const c = CRYOS[cEl.value];
    const Q_watts = parseFloat(qEl.value);

    if (isNaN(Q_watts) || Q_watts <= 0) return;

    // Heat of vaporization in Joules / kg: dh_vap * 1000
    const dh_J_kg = c.dh_vap * 1000;

    // Boil-off mass rate m_dot = Q / dh_vap  [kg / second]
    const m_dot_kg_s = Q_watts / dh_J_kg;
    const m_dot_kg_h = m_dot_kg_s * 3600;
    const m_dot_kg_day = m_dot_kg_h * 24;

    // Volumetric loss rate V_dot = m_dot / rho  [m^3 / s -> Liters / day]
    const v_dot_liters_day = (m_dot_kg_day / c.rho) * 1000;

    rResEl.textContent = v_dot_liters_day.toFixed(2) + ' Liters / Day Boil-Off';
    mResEl.textContent = 'Mass Loss: ' + m_dot_kg_h.toFixed(3) + ' kg/h (' + m_dot_kg_day.toFixed(2) + ' kg/d @ Q = ' + Q_watts + ' W Inleak into ' + c.name + ')';
  }

  cEl.addEventListener('change', update);
  qEl.addEventListener('input', update);
  update();
})();

