    const aAng = parseFloat(aEl.value);
    const h = parseInt(hEl.value, 10), k = parseInt(kEl.value, 10), l = parseInt(lEl.value, 10);

    if (isNaN(aAng) || isNaN(h) || isNaN(k) || isNaN(l) || aAng <= 0) return;
