    dResEl.textContent = dAng.toFixed(3) + ' Å (' + dNm.toFixed(4) + ' nm / ' + dPm.toFixed(1) + ' pm)';
    pResEl.textContent = '(' + h + ' ' + k + ' ' + l + ') Plane (h²+k²+l² = ' + sumSq + ')';
  }

  [aEl, hEl, kEl, lEl].forEach(el => el.addEventListener('input', update));
  update();
})();

