    const B = parseFloat(bEl.value), v = parseFloat(vEl.value);
    if (isNaN(B) || isNaN(v) || B <= 0 || v <= 0 || !m || !q) return;

    // f_c = (q * B) / (2 * pi * m)
    const fHz = (q * B) / (2 * Math.PI * m);
    // r_L = (m * v) / (q * B)
