    const fGhz = fHz / 1e9;
    const fMhz = fHz / 1e6;
    fResEl.textContent = fGhz >= 1.0 ? fGhz.toFixed(2) + ' GHz' : fMhz.toFixed(2) + ' MHz';

    const rUm = rM * 1e6;
