    }

    ktResEl.textContent = 'Dialysis Dose spKt/V = ' + spKtV.toFixed(2) + ' (' + (spKtV >= 1.20 ? 'ADEQUATE' : 'INADEQUATE') + ')';
    ktResEl.style.color = color;
