    if (isNaN(kw) || isNaN(load) || isNaN(tankL) || kw <= 0 || load <= 0 || tankL <= 0) return;

    // Standard diesel specific fuel consumption rule of thumb:
    // Full load: ~0.070 gallons per hour per kW (approx 0.265 L / kWh)
