(() => {
  'use strict';
  const x1El = document.getElementById('d3-x1'), y1El = document.getElementById('d3-y1'), z1El = document.getElementById('d3-z1');
  const x2El = document.getElementById('d3-x2'), y2El = document.getElementById('d3-y2'), z2El = document.getElementById('d3-z2');
  const distEl = document.getElementById('d3-res-dist'), midEl = document.getElementById('d3-res-mid');

  function update() {
    const x1 = parseFloat(x1El.value), y1 = parseFloat(y1El.value), z1 = parseFloat(z1El.value);
    const x2 = parseFloat(x2El.value), y2 = parseFloat(y2El.value), z2 = parseFloat(z2El.value);

    if (isNaN(x1) || isNaN(y1) || isNaN(z1) || isNaN(x2) || isNaN(y2) || isNaN(z2)) return;

    // d = sqrt((x2-x1)^2 + (y2-y1)^2 + (z2-z1)^2)
    const dist = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2) + Math.pow(z2 - z1, 2));
    // Midpoint = ((x1+x2)/2, (y1+y2)/2, (z1+z2)/2)
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2;
    const midZ = (z1 + z2) / 2;

    distEl.textContent = dist.toFixed(3) + ' units';
    midEl.textContent = '(' + midX.toFixed(2) + ', ' + midY.toFixed(2) + ', ' + midZ.toFixed(2) + ')';
  }

  [x1El, y1El, z1El, x2El, y2El, z2El].forEach(el => el.addEventListener('input', update));
  update();
})();

distillation-mccabe-thiele-minimum-reflu.js:
(() => {
  'use strict';
  const alEl = document.getElementById('fn-alpha'), xdEl = document.getElementById('fn-xd'), xbEl = document.getElementById('fn-xb');
  const nmResEl = document.getElementById('fn-res-nmin'), spResEl = document.getElementById('fn-res-sep');

  function update() {
    const alpha = parseFloat(alEl.value), x_D = parseFloat(xdEl.value), x_B = parseFloat(xbEl.value);
    if (isNaN(alpha) || isNaN(x_D) || isNaN(x_B) || alpha <= 1 || x_D <= x_B || x_D >= 1 || x_B <= 0) return;

    // Separation factor S = ( x_D / (1 - x_D) ) / ( x_B / (1 - x_B) )
    const topRatio = x_D / (1.0 - x_D);
    const bottomRatio = x_B / (1.0 - x_B);
    const S = topRatio / bottomRatio;

    // Fenske equation: N_min = ln(S) / ln(alpha)
    const N_min = Math.log(S) / Math.log(alpha);
    const practicalTrays = Math.round(N_min * 2.0);

    nmResEl.textContent = 'N_min = ' + N_min.toFixed(2) + ' Stages (~' + Math.ceil(N_min) + ' Trays)';
    spResEl.textContent = 'Separation Factor S = ' + S.toFixed(1) + ' | Practical Column: ~' + practicalTrays + ' Trays @ R = 1.3·R_min (α = ' + alpha + ')';
  }

  [alEl, xdEl, xbEl].forEach(el => el.addEventListener('input', update));
  update();
})();

dna-melting-temperature-nearest-neighbor.js:
(() => {
  'use strict';
  const seqEl = document.getElementById('dna-seq'), cEl = document.getElementById('dna-conc'), sEl = document.getElementById('dna-salt');
  const tmResEl = document.getElementById('dna-res-tm'), gcResEl = document.getElementById('dna-res-gc');

  function update() {
    const rawSeq = seqEl.value.trim().toUpperCase().replace(/[^ATGC]/g, '');
    const concNm = parseFloat(cEl.value), saltMm = parseFloat(sEl.value);

    if (rawSeq.length < 4 || isNaN(concNm) || isNaN(saltMm) || concNm <= 0 || saltMm <= 0) return;

    const n = rawSeq.length;
    let gcCount = 0;
    for (let char of rawSeq) {
      if (char === 'G' || char === 'C') gcCount++;
    }
    const atCount = n - gcCount;
    const gcPct = (gcCount / n) * 100;

    // Simple Wallace rule: 2*(A+T) + 4*(G+C)
    const wallaceTm = (2 * atCount) + (4 * gcCount);

    // Nearest-neighbor approximation formula (SantaLucia 1998):
    // Tm = 81.5 + 16.6 * log10([Na+]) + 0.41*(%GC) - (675 / N)
    const saltM = saltMm * 1e-3;
    const tm_nn = 81.5 + (16.6 * Math.log10(saltM)) + (0.41 * gcPct) - (675.0 / n);

    // Recommended PCR annealing temperature is typically Tm - 5°C
    const t_anneal = tm_nn - 5.0;

    tmResEl.textContent = 'T_m = ' + tm_nn.toFixed(1) + ' °C (Anneal: ' + t_anneal.toFixed(1) + ' °C)';
    gcResEl.textContent = 'GC: ' + gcPct.toFixed(1) + '% (' + gcCount + ' G/C, ' + atCount + ' A/T) | Length: ' + n + ' nt | Wallace Rule: ' + wallaceTm + '°C';
  }

  seqEl.addEventListener('input', update);
  cEl.addEventListener('input', update);
  sEl.addEventListener('input', update);
  update();
})();
